public static int countEven(Stack<Integer> s) {
    // מעבירים את האיברים למחסנית עזר, וסופרים את הזוגיים
    Stack<Integer> temp = new Stack<Integer>();
    int count = 0;
    while (!s.isEmpty()) {
        int x = s.pop();
        if (x % 2 == 0) {
            count++;
        }
        temp.push(x);
    }
    // מחזירים את האיברים — המחסנית חוזרת להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return count;
}

