public static void removeAll(Stack<Integer> stack, int num)
{
    // מעבירים למחסנית עזר רק את האיברים ששונים מ-num
    Stack<Integer> temp = new Stack<Integer>();
    while (!stack.isEmpty()) {
        int y = stack.pop();
        if (y != num) {
            temp.push(y);
        }
    }
    // מחזירים אותם — הסדר נשמר
    while (!temp.isEmpty()) {
        stack.push(temp.pop());
    }
}
